```zig
const CompileTimeJsonEngine = struct {
    pub fn JsonSerializer(comptime T: type) type {
        return struct {
            const Self = @This();

            pub fn serialize(allocator: std.mem.Allocator, value: T) ![]u8 {
                var buffer = std.ArrayList(u8).init(allocator);
                try serializeValue(&buffer, value);
                return buffer.toOwnedSlice();
            }

            fn serializeValue(buffer: *std.ArrayList(u8), value: T) !void {
                const info = @typeInfo(T);
                switch (info) {
                    .Struct => try serializeStruct(buffer, value),
                    .Array => try serializeArray(buffer, value),
                    .Optional => if (value) |v| try serializeValue(buffer, v) else try buffer.appendSlice("null"),
                    .Int => try std.fmt.format(buffer.writer(), "{d}", .{value}),
                    .Float => try std.fmt.format(buffer.writer(), "{d}", .{value}),
                    .Bool => try buffer.appendSlice(if (value) "true" else "false"),
                    .Pointer => |ptr_info| {
                        switch (ptr_info.size) {
                            .Slice => {
                                if (ptr_info.child == u8) {
                                    // String
                                    try buffer.append('"');
                                    try jsonEscapeString(buffer, value);
                                    try buffer.append('"');
                                } else {
                                    // Array
                                    try serializeArray(buffer, value);
                                }
                            },
                            else => @compileError("Unsupported pointer type"),
                        }
                    },
                    else => @compileError("Unsupported type for JSON serialization: " ++ @typeName(T)),
                }
            }

            fn serializeStruct(buffer: *std.ArrayList(u8), value: T) !void {
                try buffer.append('{');
                const fields = std.meta.fields(T);

                comptime var first = true;
                inline for (fields) |field| {
                    if (!first) try buffer.append(',');
                    first = false;

                    try buffer.append('"');
                    try buffer.appendSlice(field.name);
                    try buffer.appendSlice("\":");
                    try serializeValue(buffer, @field(value, field.name));
                }

                try buffer.append('}');
            }

            fn serializeArray(buffer: *std.ArrayList(u8), value: anytype) !void {
                try buffer.append('[');

                var first = true;
                for (value) |item| {
                    if (!first) try buffer.append(',');
                    first = false;
                    try serializeValue(buffer, item);
                }

                try buffer.append(']');
            }

            inline fn jsonEscapeString(buffer: *std.ArrayList(u8), str: []const u8) !void {
                // SIMD-optimized string escaping
                const Vector16 = std.meta.Vector(16, u8);
                const quote_vec = @splat(16, @as(u8, '"'));
                const backslash_vec = @splat(16, @as(u8, '\\'));
                const newline_vec = @splat(16, @as(u8, '\n'));
                const carriage_vec = @splat(16, @as(u8, '\r'));
                const tab_vec = @splat(16, @as(u8, '\t'));

                var i: usize = 0;
                while (i + 16 <= str.len) : (i += 16) {
                    const chunk: Vector16 = str[i..i+16][0..16].*;
                    const needs_escape = (chunk == quote_vec) or 
                                       (chunk == backslash_vec) or 
                                       (chunk == newline_vec) or 
                                       (chunk == carriage_vec) or 
                                       (chunk == tab_vec);

                    if (@reduce(.Or, needs_escape)) {
                        // Process byte by byte for this chunk
                        var j: usize = 0;
                        while (j < 16 and i + j < str.len) : (j += 1) {
                            try escapeCharacter(buffer, str[i + j]);
                        }
                    } else {
                        // No escaping needed, copy directly
                        try buffer.appendSlice(str[i..i+16]);
                    }
                }

                // Handle remaining bytes
                while (i < str.len) : (i += 1) {
                    try escapeCharacter(buffer, str[i]);
                }
            }

            inline fn escapeCharacter(buffer: *std.ArrayList(u8), char: u8) !void {
                switch (char) {
                    '"' => try buffer.appendSlice("\\\""),
                    '\\' => try buffer.appendSlice("\\\\"),
                    '\n' => try buffer.appendSlice("\\n"),
                    '\r' => try buffer.appendSlice("\\r"),
                    '\t' => try buffer.appendSlice("\\t"),
                    else => try buffer.append(char),
                }
            }
        };
    }

    pub fn JsonDeserializer(comptime T: type) type {
        return struct {
            const Self = @This();

            pub fn deserialize(allocator: std.mem.Allocator, json_str: []const u8) !T {
                var tokenizer = JsonTokenizer.init(json_str);
                return parseValue(T, &tokenizer, allocator);
            }

            fn parseValue(comptime ValueType: type, tokenizer: *JsonTokenizer, allocator: std.mem.Allocator) !ValueType {
                const info = @typeInfo(ValueType);
                switch (info) {
                    .Struct => return parseStruct(ValueType, tokenizer, allocator),
                    .Array => |arr_info| return parseArray(ValueType, arr_info, tokenizer, allocator),
                    .Optional => |opt_info| {
                        if (tokenizer.peek() == .null_literal) {
                            _ = tokenizer.next();
                            return null;
                        }
                        return try parseValue(opt_info.child, tokenizer, allocator);
                    },
                    .Int => return try parseInt(ValueType, tokenizer),
                    .Float => return try parseFloat(ValueType, tokenizer),
                    .Bool => return try parseBool(tokenizer),
                    .Pointer => |ptr_info| {
                        switch (ptr_info.size) {
                            .Slice => {
                                if (ptr_info.child == u8) {
                                    return try parseString(tokenizer, allocator);
                                } else {
                                    return try parseSlice(ptr_info.child, tokenizer, allocator);
                                }
                            },
                            else => @compileError("Unsupported pointer type"),
                        }
                    },
                    else => @compileError("Unsupported type for JSON deserialization: " ++ @typeName(ValueType)),
                }
            }

            fn parseStruct(comptime StructType: type, tokenizer: *JsonTokenizer, allocator: std.mem.Allocator) !StructType {
                if (tokenizer.next() != .object_begin) return error.ExpectedObject;

                var result: StructType = undefined;
                const fields = std.meta.fields(StructType);

                // Initialize optional fields to null
                inline for (fields) |field| {
                    if (@typeInfo(field.type) == .Optional) {
                        @field(result, field.name) = null;
                    }
                }

                while (tokenizer.peek() != .object_end) {
                    const key_token = tokenizer.next();
                    if (key_token != .string) return error.ExpectedString;

                    if (tokenizer.next() != .colon) return error.ExpectedColon;

                    const key = tokenizer.getString(key_token);

                    // Compile-time field matching
                    comptime var found = false;
                    inline for (fields) |field| {
                        if (std.mem.eql(u8, field.name, key)) {
                            @field(result, field.name) = try parseValue(field.type, tokenizer, allocator);
                            found = true;
                            break;
                        }
                    }

                    if (!found) {
                        // Skip unknown field
                        _ = try skipValue(tokenizer);
                    }

                    if (tokenizer.peek() == .comma) {
                        _ = tokenizer.next();
                    }
                }

                _ = tokenizer.next(); // consume object_end
                return result;
            }

            // Additional parsing methods...
        };
    }

    const JsonTokenizer = struct {
        input: []const u8,
        pos: usize,

        const Token = union(enum) {
            object_begin,
            object_end,
            array_begin,
            array_end,
            string: []const u8,
            number: []const u8,
            boolean: bool,
            null_literal,
            colon,
            comma,
            eof,
        };

        pub fn init(input: []const u8) JsonTokenizer {
            return JsonTokenizer{
                .input = input,
                .pos = 0,
            };
        }

        pub fn next(self: *JsonTokenizer) Token {
            self.skipWhitespace();

            if (self.pos >= self.input.len) return .eof;

            const char = self.input[self.pos];
            switch (char) {
                '{' => {
                    self.pos += 1;
                    return .object_begin;
                },
                '}' => {
                    self.pos += 1;
                    return .object_end;
                },
                '[' => {
                    self.pos += 1;
                    return .array_begin;
                },
                ']' => {
                    self.pos += 1;
                    return .array_end;
                },
                ':' => {
                    self.pos += 1;
                    return .colon;
                },
                ',' => {
                    self.pos += 1;
                    return .comma;
                },
                '"' => return self.parseString(),
                't', 'f' => return self.parseBoolean(),
                'n' => return self.parseNull(),
                '0'...'9', '-' => return self.parseNumber(),
                else => return .eof,
            }
        }

        pub fn peek(self: *JsonTokenizer) Token {
            const saved_pos = self.pos;
            const token = self.next();
            self.pos = saved_pos;
            return token;
        }

        fn skipWhitespace(self: *JsonTokenizer) void {
            while (self.pos < self.input.len) {
                switch (self.input[self.pos]) {
                    ' ', '\t', '\n', '\r' => self.pos += 1,
                    else => break,
                }
            }
        }

        fn parseString(self: *JsonTokenizer) Token {
            const start = self.pos;
            self.pos += 1; // Skip opening quote

            while (self.pos < self.input.len and self.input[self.pos] != '"') {
                if (self.input[self.pos] == '\\') {
                    self.pos += 2; // Skip escape sequence
                } else {
                    self.pos += 1;
                }
            }

            if (self.pos < self.input.len) {
                self.pos += 1; // Skip closing quote
            }

            return Token{ .string = self.input[start + 1..self.pos - 1] };
        }

        // Additional tokenizer methods...
    };
};

