const BranchOptimizedHandlers = struct {
    // Hot path optimization with branch prediction hints
    pub fn handleRequest(req: *Request, res: *Response, providers: Providers) !void {
        const path = req.head.target;
        const method = req.head.method;

        // Most common paths first with likelihood hints
        if (@likely(method == .GET)) {
            if (@likely(std.mem.eql(u8, path, "/"))) {
                return handleRoot(res);
            } else if (@likely(std.mem.startsWith(u8, path, "/research/status/"))) {
                return handleStatus(req, res);
            } else if (@unlikely(std.mem.startsWith(u8, path, "/research/stream/"))) {
                return handleSSE(req, res);
            } else if (@unlikely(std.mem.startsWith(u8, path, "/download/"))) {
                return handleDownload(req, res);
            }
        } else if (@unlikely(method == .POST)) {
            if (@unlikely(std.mem.eql(u8, path, "/research/start"))) {
                return handleStart(req, res, providers);
            }
        }

        // 404 case - least likely
        res.status = .not_found;
        try res.do();
    }

    // Cache-optimized job structure
    const CacheOptimizedJob = struct {
        // Hot data - first cache line (64 bytes)
        id: [32]u8 align(64),
        state: JobState align(1),

        // Padding to fill cache line
        _padding1: [64 - 32 - @sizeOf(JobState)]u8 = undefined,

        // Cold data - second cache line
        result: ?JobResult align(64),
        _padding2: [64 - @sizeOf(?JobResult)]u8 = undefined,

        pub fn getState(self: *const CacheOptimizedJob) JobState {
            // Prefetch next cache line for result if state indicates completion
            if (@likely(self.state.progress == 100)) {
                @prefetch(&self.result, .read, 3, .data);
            }
            return self.state;
        }
    };

    // SIMD-optimized string operations
    pub fn fastStringCompare(a: []const u8, b: []const u8) bool {
        if (a.len != b.len) return false;

        const Vector32 = std.meta.Vector(32, u8);
        var i: usize = 0;

        // Process 32 bytes at a time with AVX2
        while (i + 32 <= a.len) : (i += 32) {
            const chunk_a: Vector32 = a[i..i+32][0..32].*;
            const chunk_b: Vector32 = b[i..i+32][0..32].*;

            if (!@reduce(.And, chunk_a == chunk_b)) {
                return false;
            }
        }

        // Handle remaining bytes
        return std.mem.eql(u8, a[i..], b[i..]);
    }

    // Assembly-optimized memory copy for critical paths
    pub fn fastMemcpy(dest: []u8, src: []const u8) void {
        const len = @min(dest.len, src.len);

        if (len >= 64) {
            // Use assembly for large copies
            asm volatile (
                \\cld
                \\rep movsq
                : [dest] "={rdi}" (-> usize),
                  [src] "={rsi}" (-> usize),
                  [count] "={rcx}" (-> usize),
                : [dest] "{rdi}" (@intFromPtr(dest.ptr)),
                  [src] "{rsi}" (@intFromPtr(src.ptr)),
                  [count] "{rcx}" (len / 8),
                : "memory"
            );

            // Handle remaining bytes
            const remaining = len % 8;
            if (remaining > 0) {
                @memcpy(dest[len - remaining..len], src[len - remaining..len]);
            }
        } else {
            // Use builtin for small copies
            @memcpy(dest[0..len], src[0..len]);
        }
    }
};

// CPU cache-friendly hash table implementation
const CacheFriendlyHashMap = struct {
    const Self = @This();
    const CACHE_LINE_SIZE = 64;
    const ENTRIES_PER_BUCKET = CACHE_LINE_SIZE / @sizeOf(Entry);

    const Entry = struct {
        hash: u32,
        key_len: u8,
        key_data: [23]u8, // Total 32 bytes per entry
        value: *Job,
    };

    const Bucket = struct {
        entries: [ENTRIES_PER_BUCKET]Entry align(64),
        count: u8,
        _padding: [CACHE_LINE_SIZE - ENTRIES_PER_BUCKET * @sizeOf(Entry) - 1]u8,
    };

    buckets: []Bucket,
    bucket_count: u32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, capacity: u32) !Self {
        const bucket_count = std.math.ceilPowerOfTwo(u32, capacity / ENTRIES_PER_BUCKET) catch return error.TooLarge;
        const buckets = try allocator.alignedAlloc(Bucket, 64, bucket_count);

        // Initialize buckets
        for (buckets) |*bucket| {
            bucket.count = 0;
        }

        return Self{
            .buckets = buckets,
            .bucket_count = bucket_count,
            .allocator = allocator,
        };
    }

    pub fn put(self: *Self, key: []const u8, value: *Job) !void {
        if (key.len > 23) return error.KeyTooLong;

        const hash = xxHash32(key);
        const bucket_index = hash & (self.bucket_count - 1);
        const bucket = &self.buckets[bucket_index];

        // Try to find empty slot in bucket
        if (bucket.count < ENTRIES_PER_BUCKET) {
            const entry = &bucket.entries[bucket.count];
            entry.hash = hash;
            entry.key_len = @intCast(u8, key.len);
            @memcpy(entry.key_data[0..key.len], key);
            entry.value = value;
            bucket.count += 1;
            return;
        }

        // Bucket full - need to resize or use overflow handling
        return error.BucketFull;
    }

    pub fn get(self: *Self, key: []const u8) ?*Job {
        const hash = xxHash32(key);
        const bucket_index = hash & (self.bucket_count - 1);
        const bucket = &self.buckets[bucket_index];

        // Prefetch the entire bucket (one cache line)
        @prefetch(bucket, .read, 3, .data);

        // Search within the bucket
        var i: u8 = 0;
        while (i < bucket.count) : (i += 1) {
            const entry = &bucket.entries[i];
            if (@likely(entry.hash == hash and 
                       entry.key_len == key.len and
                       std.mem.eql(u8, entry.key_data[0..entry.key_len], key))) {
                return entry.value;
            }
        }

        return null;
    }

    inline fn xxHash32(data: []const u8) u32 {
        // Optimized 32-bit hash for short strings
        const PRIME32_1: u32 = 0x9E3779B1;
        const PRIME32_2: u32 = 0x85EBCA77;
        const PRIME32_3: u32 = 0xC2B2AE3D;
        const PRIME32_4: u32 = 0x27D4EB2F;
        const PRIME32_5: u32 = 0x165667B1;

        var hash: u32 = PRIME32_5 + @as(u32, @intCast(data.len));

        var i: usize = 0;
        while (i + 4 <= data.len) : (i += 4) {
            const val = std.mem.readIntLittle(u32, data[i..i+4][0..4]);
            hash = std.math.rotl(u32, hash + val * PRIME32_3, 17) * PRIME32_4;
        }

        while (i < data.len) : (i += 1) {
            hash = std.math.rotl(u32, hash + @as(u32, data[i]) * PRIME32_5, 11) * PRIME32_1;
        }

        hash ^= hash >> 15;
        hash *= PRIME32_2;
        hash ^= hash >> 13;
        hash *= PRIME32_3;
        hash ^= hash >> 16;

        return hash;
    }
};
