const HardwareOptimizedKernel = struct {
    // CPU feature detection és optimalizált code path selection
    const CpuFeatures = struct {
        has_avx512: bool,
        has_avx2: bool,
        has_pclmulqdq: bool,
        has_aes_ni: bool,
        has_bmi2: bool,
        cache_line_size: u32,
        l1_cache_size: u32,
        l2_cache_size: u32,
        l3_cache_size: u32,
        numa_nodes: u32,

        pub fn detect() CpuFeatures {
            var features: CpuFeatures = undefined;

            // CPUID intrinsic használata feature detection-höz
            const cpuid_result = asm volatile (
                \\cpuid
                : [eax] "={eax}" (-> u32),
                  [ebx] "={ebx}" (-> u32),
                  [ecx] "={ecx}" (-> u32),
                  [edx] "={edx}" (-> u32),
                : [leaf] "{eax}" (@as(u32, 1)),
                  [subleaf] "{ecx}" (@as(u32, 0)),
            );

            features.has_avx2 = (cpuid_result[2] & (1 << 5)) != 0;
            features.has_aes_ni = (cpuid_result[2] & (1 << 25)) != 0;

            // Cache size detection
            features.cache_line_size = getCacheLineSize();
            features.l3_cache_size = getL3CacheSize();

            return features;
        }

        inline fn getCacheLineSize() u32 {
            const cpuid_result = asm volatile (
                \\cpuid
                : [eax] "={eax}" (-> u32),
                  [ebx] "={ebx}" (-> u32),
                  [ecx] "={ecx}" (-> u32),
                  [edx] "={edx}" (-> u32),
                : [leaf] "{eax}" (@as(u32, 0x80000006)),
                  [subleaf] "{ecx}" (@as(u32, 0)),
            );
            return @intCast(u32, cpuid_result[2] & 0xFF);
        }
    };

    // AVX-512 optimalizált memory operations
    pub fn avx512Memcpy(dest: [*]u8, src: [*]const u8, len: usize) void {
        if (cpu_features.has_avx512 and len >= 64) {
            var i: usize = 0;
            while (i + 64 <= len) : (i += 64) {
                asm volatile (
                    \\vmovdqu64 (%[src]), %%zmm0
                    \\vmovdqu64 %%zmm0, (%[dest])
                    :
                    : [src] "r" (src + i),
                      [dest] "r" (dest + i),
                    : "zmm0", "memory"
                );
            }
            // Handle remaining bytes with standard copy
            @memcpy(dest[i..len], src[i..len]);
        } else {
            @memcpy(dest[0..len], src[0..len]);
        }
    }

    // Hardware-accelerated hash computation using AES-NI
    pub fn aesniHash(data: []const u8) u64 {
        if (!cpu_features.has_aes_ni) return fallbackHash(data);

        var hash: u128 = 0x0123456789ABCDEF0123456789ABCDEF;
        var i: usize = 0;

        while (i + 16 <= data.len) : (i += 16) {
            const block = std.mem.readIntLittle(u128, data[i..i+16][0..16]);
            hash = asm volatile (
                \\aesenc %[block], %[hash]
                : [hash] "=x" (-> u128),
                : [hash] "0" (hash),
                  [block] "x" (block),
            );
        }

        // Final reduction
        return @truncate(u64, hash ^ (hash >> 64));
    }

    const cpu_features = CpuFeatures.detect();
};
