**NUMA-Aware Memory Management**

Modern szervereken a NUMA topology kihasználása kritikus:

```zig
const NumaOptimizedAllocator = struct {
    const Self = @This();

    const NumaNode = struct {
        id: u32,
        cpu_mask: u64,
        memory_start: usize,
        memory_size: usize,
        allocator: std.heap.GeneralPurposeAllocator(.{}),

        pub fn init(node_id: u32) NumaNode {
            // Set CPU affinity to this NUMA node
            const cpu_set = linux.cpu_set_t{};
            var i: u32 = 0;
            while (i < 64) : (i += 1) {
                if (isNodeCpu(node_id, i)) {
                    linux.CPU_SET(i, &cpu_set);
                }
            }

            _ = linux.sched_setaffinity(0, @sizeOf(linux.cpu_set_t), &cpu_set);

            return NumaNode{
                .id = node_id,
                .cpu_mask = getCpuMask(node_id),
                .memory_start = getNodeMemoryStart(node_id),
                .memory_size = getNodeMemorySize(node_id),
                .allocator = std.heap.GeneralPurposeAllocator(.{}){},
            };
        }
    };

    nodes: []NumaNode,
    current_cpu: std.atomic.Atomic(u32),

    pub fn init(allocator: std.mem.Allocator) !Self {
        const node_count = getNumaNodeCount();
        const nodes = try allocator.alloc(NumaNode, node_count);

        for (nodes, 0..) |*node, i| {
            node.* = NumaNode.init(@intCast(u32, i));
        }

        return Self{
            .nodes = nodes,
            .current_cpu = std.atomic.Atomic(u32).init(0),
        };
    }

    pub fn alloc(self: *Self, size: usize) ![]u8 {
        const cpu = getCurrentCpu();
        const node_id = cpuToNumaNode(cpu);
        return self.nodes[node_id].allocator.alloc(u8, size);
    }

    pub fn allocLocal(self: *Self, size: usize) ![]u8 {
        // Allocate on the NUMA node of the current thread
        const cpu = asm volatile (
            \\rdtscp
            : [cpu] "={ecx}" (-> u32),
            :
            : "eax", "edx"
        );

        const node_id = cpuToNumaNode(cpu);
        return self.nodes[node_id].allocator.alloc(u8, size);
    }

    inline fn getCurrentCpu() u32 {
        return asm volatile (
            \\rdtscp
            : [cpu] "={ecx}" (-> u32),
            :
            : "eax", "edx"
        );
    }

    inline fn cpuToNumaNode(cpu: u32) u32 {
        // Platform-specific mapping - ezt a /sys/devices/system/node alapján kell meghatározni
        return cpu / 16; // Példa: 16 core per NUMA node
    }
};
