const DpdkIntegration = struct {
    const Self = @This();

    // DPDK környezet inicializálás
    const DpdkConfig = struct {
        memory_channels: u32 = 4,
        memory_size: u32 = 1024, // MB
        core_mask: []const u8 = "0xF", // CPU cores to use
        port_mask: []const u8 = "0x1", // Network ports
        huge_pages: bool = true,

        pub fn init() !DpdkConfig {
            return DpdkConfig{};
        }
    };

    const PacketBuffer = struct {
        data: [2048]u8 align(64),
        length: u16,
        port: u8,
        timestamp: u64,

        pub fn asHttpRequest(self: *const PacketBuffer) []const u8 {
            return self.data[0..self.length];
        }
    };

    const RxQueue = struct {
        packets: [4096]*PacketBuffer align(64),
        head: std.atomic.Atomic(u32),
        tail: std.atomic.Atomic(u32),

        pub fn dequeue(self: *RxQueue) ?*PacketBuffer {
            const head = self.head.load(.Acquire);
            const tail = self.tail.load(.Acquire);

            if (head == tail) return null;

            const packet = self.packets[head % 4096];
            _ = self.head.compareAndSwap(head, head + 1, .AcqRel, .Acquire);
            return packet;
        }

        pub fn enqueue(self: *RxQueue, packet: *PacketBuffer) bool {
            const tail = self.tail.load(.Acquire);
            const head = self.head.load(.Acquire);

            if ((tail + 1) % 4096 == head % 4096) return false; // Queue full

            self.packets[tail % 4096] = packet;
            _ = self.tail.compareAndSwap(tail, tail + 1, .AcqRel, .Acquire);
            return true;
        }
    };

    config: DpdkConfig,
    rx_queues: []RxQueue,
    packet_pool: []PacketBuffer,
    worker_threads: []std.Thread,

    pub fn init(allocator: std.mem.Allocator) !Self {
        const config = try DpdkConfig.init();

        // Initialize DPDK EAL (Environment Abstraction Layer)
        const eal_args = [_][*:0]const u8{
            "zig_server",
            "-c", config.core_mask.ptr,
            "-n", "4", // memory channels
            "--huge-dir", "/mnt/huge",
            "--file-prefix", "zig_server",
        };

        const eal_result = c.rte_eal_init(@intCast(c_int, eal_args.len), @ptrCast([*c][*c]u8, &eal_args));
        if (eal_result < 0) return error.DpdkInitFailed;

        // Initialize memory pool for packet buffers
        const packet_pool = try allocator.alignedAlloc(PacketBuffer, 64, 65536);

        // Initialize RX queues (one per CPU core)
        const core_count = @intCast(usize, eal_result);
        const rx_queues = try allocator.alloc(RxQueue, core_count);

        for (rx_queues) |*queue| {
            queue.* = RxQueue{
                .packets = undefined,
                .head = std.atomic.Atomic(u32).init(0),
                .tail = std.atomic.Atomic(u32).init(0),
            };
        }

        return Self{
            .config = config,
            .rx_queues = rx_queues,
            .packet_pool = packet_pool,
            .worker_threads = try allocator.alloc(std.Thread, core_count),
        };
    }

    pub fn startWorkers(self: *Self) !void {
        for (self.worker_threads, 0..) |*thread, core_id| {
            thread.* = try std.Thread.spawn(.{}, workerLoop, .{ self, @intCast(u32, core_id) });
        }
    }

    fn workerLoop(self: *Self, core_id: u32) void {
        // Set thread affinity to specific CPU core
        const cpu_set = std.os.linux.cpu_set_t{};
        std.os.linux.CPU_SET(core_id, &cpu_set);
        _ = std.os.linux.sched_setaffinity(0, @sizeOf(std.os.linux.cpu_set_t), &cpu_set);

        const queue = &self.rx_queues[core_id];
        var batch_buffer: [32]*PacketBuffer = undefined;

        while (true) {
            // Batch packet reception for better performance
            const received = receivePacketBatch(core_id, &batch_buffer);

            for (batch_buffer[0..received]) |packet| {
                if (isHttpPacket(packet)) {
                    processHttpPacket(packet, core_id);
                }
                // Return packet to pool
                returnPacketToPool(packet);
            }

            // Yield CPU if no packets received
            if (received == 0) {
                asm volatile ("pause");
            }
        }
    }

    fn receivePacketBatch(port_id: u32, buffer: []?*PacketBuffer) u32 {
        // Direct hardware queue polling - bypass kernel completely
        return asm volatile (
            \\call receive_packets_asm
            : [count] "={eax}" (-> u32),
            : [port] "{rdi}" (port_id),
              [buffer] "{rsi}" (buffer.ptr),
              [max_count] "{rdx}" (buffer.len),
            : "memory"
        );
    }

    fn processHttpPacket(packet: *PacketBuffer, core_id: u32) void {
        // Zero-copy HTTP processing directly on packet buffer
        const request_data = packet.asHttpRequest();

