const IoUringHttpServer = struct {
    const Self = @This();
    const QUEUE_DEPTH = 4096;
    const BUFFER_SIZE = 64 * 1024;

    ring: std.os.linux.io_uring,
    buffers: [][]u8,
    connections: std.AutoHashMap(i32, *Connection),
    allocator: std.mem.Allocator,

    const Connection = struct {
        fd: i32,
        buffer: []u8,
        state: enum { reading, processing, writing },
        bytes_read: u32,
        bytes_to_write: u32,
        response_data: []u8,
    };

    pub fn init(allocator: std.mem.Allocator) !Self {
        var ring: std.os.linux.io_uring = undefined;

        // Initialize io_uring with advanced features
        var params = std.os.linux.io_uring_params{
            .flags = std.os.linux.IORING_SETUP_SQPOLL | // Kernel polling thread
                    std.os.linux.IORING_SETUP_IOPOLL |  // High-performance polling
                    std.os.linux.IORING_SETUP_CQSIZE |  // Custom completion queue size
                    std.os.linux.IORING_SETUP_CLAMP,    // Clamp queue sizes
            .sq_thread_idle = 2000, // 2 second idle timeout
            .cq_entries = QUEUE_DEPTH * 2,
            .wq_fd = 0,
            .resv = [3]u32{ 0, 0, 0 },
            .sq_thread_cpu = 0, // Pin to CPU 0
        };

        const result = std.os.linux.io_uring_setup(QUEUE_DEPTH, &params);
        if (result < 0) return error.IoUringSetupFailed;

        // Initialize the ring structure
        try std.os.linux.io_uring_queue_init(QUEUE_DEPTH, &ring, 0);

        // Pre-allocate buffers
        const buffers = try allocator.alloc([]u8, QUEUE_DEPTH);
        for (buffers) |*buffer| {
            buffer.* = try allocator.alignedAlloc(u8, 4096, BUFFER_SIZE);
        }

        return Self{
            .ring = ring,
            .buffers = buffers,
            .connections = std.AutoHashMap(i32, *Connection).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn acceptConnections(self: *Self, listen_fd: i32) !void {
        while (true) {
            // Submit accept operation
            const sqe = std.os.linux.io_uring_get_sqe(&self.ring);
            if (sqe == null) {
                // Submit pending operations and wait
                _ = try std.os.linux.io_uring_submit(&self.ring);
                continue;
            }

            // Prepare accept operation
            std.os.linux.io_uring_prep_accept(sqe, listen_fd, null, null, 0);
            sqe.user_data = @intFromPtr(listen_fd); // Use fd as identifier

            // Submit and process completions
            const submitted = try std.os.linux.io_uring_submit(&self.ring);

            // Process completed operations
            var cqe_count: u32 = 0;
            while (cqe_count < submitted) {
                var cqe: *std.os.linux.io_uring_cqe = undefined;
                const ret = std.os.linux.io_uring_wait_cqe(&self.ring, &cqe);
                if (ret < 0) continue;

                try self.processCompletion(cqe);
                std.os.linux.io_uring_cqe_seen(&self.ring, cqe);
                cqe_count += 1;
            }
        }
    }

    fn processCompletion(self: *Self, cqe: *std.os.linux.io_uring_cqe) !void {
        const user_data = cqe.user_data;
        const result = cqe.res;

        if (result < 0) {
            // Error occurred
            std.log.err("io_uring operation failed: {}", .{result});
            return;
        }

        // Determine operation type based on user_data
        if (user_data < 1024) {
            // This is an accept operation
            const client_fd = result;
            try self.startClientConnection(client_fd);
        } else {
            // This is a client operation
            const connection = @as(*Connection, @ptrFromInt(user_data));
            try self.processClientOperation(connection, result);
        }
    }

    fn startClientConnection(self: *Self, client_fd: i32) !void {
        const connection = try self.allocator.create(Connection);
        connection.* = Connection{
            .fd = client_fd,
            .buffer = self.buffers[client_fd % self.buffers.len], // Simple buffer assignment
            .state = .reading,
            .bytes_read = 0,
            .bytes_to_write = 0,
            .response_data = undefined,
        };

        try self.connections.put(client_fd, connection);

        // Submit read operation
        const sqe = std.os.linux.io_uring_get_sqe(&self.ring);
        if (sqe != null) {
            std.os.linux.io_uring_prep_read(sqe, client_fd, connection.buffer.ptr, BUFFER_SIZE, 0);
            sqe.user_data = @intFromPtr(connection);
        }
    }

    fn processClientOperation(self: *Self, connection: *Connection, result: i32) !void {
        switch (connection.state) {
            .reading => {
                connection.bytes_read += @intCast(u32, result);

                // Check if we have a complete HTTP request
                const request_data = connection.buffer[0..connection.bytes_read];
                if (std.mem.indexOf(u8, request_data, "\r\n\r\n")) |_| {
                    // Complete request received, process it
                    connection.state = .processing;
                    try self.processHttpRequest(connection);
                } else if (connection.bytes_read < BUFFER_SIZE) {
                    // Continue reading
                    const sqe = std.os.linux.io_uring_get_sqe(&self.ring);
                    if (sqe != null) {
                        std.os.linux.io_uring_prep_read(
                            sqe, 
                            connection.fd, 
                            connection.buffer.ptr + connection.bytes_read, 
                            BUFFER_SIZE - connection.bytes_read, 
                            0
                        );
                        sqe.user_data = @intFromPtr(connection);
                    }
                }
            },
            .processing => {
                // Should not reach here as processing is synchronous
                unreachable;
            },
            .writing => {
                // Write operation completed
                const bytes_written = @intCast(u32, result);
                connection.bytes_to_write -= bytes_written;

                if (connection.bytes_to_write == 0) {
                    // Response fully sent, close connection or keep alive
                    try self.closeConnection(connection);
                } else {
                    // Continue writing remaining data
                    const sqe = std.os.linux.io_uring_get_sqe(&self.ring);
                    if (sqe != null) {
                        const written_offset = connection.response_data.len - connection.bytes_to_write;
                        std.os.linux.io_uring_prep_write(
                            sqe,
                            connection.fd,
                            connection.response_data.ptr + written_offset,
                            connection.bytes_to_write,
                            0
                        );
                        sqe.user_data = @intFromPtr(connection);
                    }
                }
            },
        }
    }

