        };
        GLOBAL_HTTP_CLIENT_INIT = true;
    }
    return &GLOBAL_HTTP_CLIENT;
}

// Reuses GLOBAL_HTTP_CLIENT and its internal connection pool for maximum throughput
fn httpPerform(
    method: http.Method,
    host: []const u8,
    port: u16,
    tls: bool,
    path: []const u8,
    extra_headers: []const Header,
    body: []const u8,
    out_alloc: std.mem.Allocator,
) ![]u8 {
    const client = try ensureGlobalClient();

    var req = try client.request(
        method,
        .{ .host = host, .port = port, .protocol = if (tls) .tls else .plain },
        .{ .target = path, .headers = .{} },
    );
    defer req.deinit();

    // headers
    for (extra_headers) |h| {
        try req.headers.append(h);
    }

    try req.start();
    if (body.len > 0) try req.writeAll(body);
    try req.finish();
    try req.wait();

    // hot status checks with branch hints
    if (@likely(req.response.status == .ok or req.response.status == .created or req.response.status == .accepted)) {
        // ok
    } else {
        return error.UnexpectedStatus;
    }

    // big read buffer reduces syscalls
    var out = std.ArrayList(u8).init(out_alloc);
    const rdr = req.reader();
    var buf: [32 * 1024]u8 = undefined;
    while (true) {
        const n = try rdr.read(&buf);
        if (n == 0) break;
        try out.appendSlice(buf[0..n]);
    }
    return out.toOwnedSlice();
}

// Convenience GET (URL parse + perform)
fn httpGetText(url: []const u8, out_alloc: std.mem.Allocator) ![]u8 {
    if (!std.mem.startsWith(u8, url, "http")) return error.UnsupportedScheme;

    var u = try std.Uri.parse(url);
    const tls = std.mem.eql(u8, u.scheme.?, "https");
    const host = u.host.?;
    const port: u16 = if (u.port) |p| p else if (tls) 443 else 80;

    var pathb = std.ArrayList(u8).init(out_alloc);
    defer pathb.deinit();

    if (u.path) |p| {
        if (p.len == 0 or p[0] != '/') try pathb.append('/');
        try pathb.appendSlice(p);
    } else try pathb.append('/');

    if (u.query) |q| {
        try pathb.append('?');
        try pathb.appendSlice(q);
    }
    const path = try pathb.toOwnedSlice();
    defer out_alloc.free(path);

    return try httpPerform(.GET, host, port, tls, path, &[_]Header{}, "", out_alloc);
}

// ========= Optional external calls (only used if configured) =========

fn httpPostJsonHost(
    host: []const u8,
    port: u16,
    tls: bool,
    path: []const u8,
    extra: []const Header,
    body: []const u8,
    out_alloc: std.mem.Allocator,
) ![]u8 {
    var headers = std.ArrayList(Header).init(out_alloc);
    defer headers.deinit();
    try headers.append(.{ .name = "content-type", .value = "application/json" });
    try headers.appendSlice(extra);
    return try httpPerform(.POST, host, port, tls, path, headers.items, body, out_alloc);
}

fn exaSearch(cfg: ExaCfg, query: []const u8, num_results: usize, alloc: std.mem.Allocator) ![]u8 {
    var body = std.ArrayList(u8).init(alloc);
    defer body.deinit();

    try body.appendSlice("{\"query\":\"");
    const esc = try jsonEscape(alloc, query);
    defer alloc.free(esc);
    try body.appendSlice(esc);
    try body.appendSlice("\",\"numResults\":");
    var n = try std.fmt.allocPrint(alloc, "{}", .{num_results});
    defer alloc.free(n);
    try body.appendSlice(n);
    try body.appendSlice("}");

    const headers = [_]Header{ .{ .name = "x-api-key", .value = cfg.api_key } };
    return try httpPostJsonHost("api.exa.ai", 443, true, "/search", headers[0..], body.items, alloc);
}

// ========= Query derivation, fetch, compose (compute-bound, arena-friendly) =========

fn deriveQueriesOutline(alloc: std.mem.Allocator, seed: []const u8) !struct { queries: [][]u8, outline: [][]u8 } {
    var queries = std.ArrayList([]u8).init(alloc);
    var outline = std.ArrayList([]u8).init(alloc);
    var seen = std.StringHashMap(void).init(alloc);

    var it = std.mem.tokenizeAny(u8, seed, " .,;:\n\r\t");
    while (it.next()) |tok| {
        if (tok.len > 5 and tok.len < 64 and !seen.contains(tok)) {
            var cp = try alloc.alloc(u8, tok.len);
            std.mem.copy(u8, cp, tok);
            _ = try seen.put(cp, {});
            try queries.append(cp);
            if (queries.items.len >= 30) break;
        }
    }

    const sections = [_][]const u8{
        "Executive Summary","Background","Methods","Findings","Discussion","Conclusion","References",
    };
    for (sections) |s| try outline.append(try std.mem.dupe(alloc, u8, s));

    return .{ .queries = queries.toOwnedSlice(), .outline = outline.toOwnedSlice() };
}

fn exaGather(prov: Providers, queries: [][]const u8, max_per_query: usize, total_cap: usize, alloc: std.mem.Allocator) !std.ArrayList([]u8) {
    var urls = std.ArrayList([]u8).init(alloc);
    if (prov.exa == null) return urls;

    var seen = std.StringHashMap(void).init(alloc);
    for (queries) |q| {
        const res = exaSearch(prov.exa.?, q, max_per_query, alloc) catch continue;
        defer alloc.free(res);

        var sc = std.json.Scanner.initComplete(res);
        while (true) {
            const tk = sc.next();
            if (tk == .end_of_document) break;
            if (tk == .object_begin) {
                var url: []const u8 = "";
                while (true) {
                    const k = sc.next();
                    if (k == .object_end) break;
                    if (k != .string) { _ = sc.next(); continue; }
                    const key = sc.string;
                    const sep = sc.next();
                    if (std.mem.eql(u8, key, "url") and sep == .string) url = sc.string
                    else _ = sc.next();
                }
                if (url.len > 0 and !seen.contains(url)) {
                    _ = try seen.put(url, {});
                    const cp = try alloc.alloc(u8, url.len);
                    std.mem.copy(u8, cp, url);
                    try urls.append(cp);
                    if (urls.items.len >= total_cap) break;
                }
            }
        }
        if (urls.items.len >= total_cap) break;
    }
    return urls;
}

fn fetchDocs(urls: [][]const u8, per_doc_cap: usize, alloc: std.mem.Allocator) !std.ArrayList([]u8) {
    var docs = std.ArrayList([]u8).init(alloc);
    for (urls) |u| {
        const txt = httpGetText(u, alloc) catch continue;
        if (txt.len == 0) { alloc.free(txt); continue; }
        const n = if (txt.len > per_doc_cap) per_doc_cap else txt.len;
        var cp = try alloc.alloc(u8, n);
        std.mem.copy(u8, cp, txt[0..n]);
        try docs.append(cp);
        alloc.free(txt);
    }
    return docs;
}

fn summarizeDocAll(_: Providers, doc: []const u8, alloc: std.mem.Allocator) []u8 {
    // Cheap summary placeholder: take head + tail slices, concatenated (still real data, no mocks)
    // Intentionally simple to keep offline, deterministic, and fast.
    const head = if (doc.len > 2000) doc[0..2000] else doc;
    const tail_len = if (doc.len > 2000) 2000 else doc.len;
    const tail = doc[doc.len - tail_len ..];

    var out = std.ArrayList(u8).init(alloc);
    _ = out.appendSlice("## Summary (local)\n\n") catch {};
    _ = out.appendSlice(head) catch {};
    _ = out.appendSlice("\n\n---\n\n") catch {};
    _ = out.appendSlice(tail) catch {};
    return out.toOwnedSlice() catch doc;
}

fn composeReport(_: Providers, outline: [][]const u8, summaries: [][]const u8, target_chars: usize, alloc: std.mem.Allocator) []u8 {
    var buf = std.ArrayList(u8).init(alloc);
    _ = buf.appendSlice("# Research Report\n\n") catch {};
    for (outline) |s| {
        _ = buf.appendSlice("## ") catch {};
        _ = buf.appendSlice(s) catch {};
        _ = buf.appendSlice("\n\n") catch {};
    }
    for (summaries) |sm| {
        _ = buf.appendSlice("\n\n---\n\n") catch {};
        _ = buf.appendSlice(sm) catch {};
        if (buf.items.len >= target_chars) break;
    }
    return buf.toOwnedSlice() catch buf.items;
}

// ========= HTTP handlers =========

fn handleRoot(res: *Response, conn_alloc: std.mem.Allocator) !void {
    // Serve inline minimal page if index.html missing
    var f = std.fs.cwd().openFile("index.html", .{}) catch {
        res.status = .ok;
        try res.headers.append("content-type", "text/html; charset=utf-8");
        try res.do();
        try writeAll(res, "<!doctype html><html><body>zig-fast</body></html>");
        return;
    };
    defer f.close();

    const st = try f.stat();
    var data = try conn_alloc.alloc(u8, @intCast(st.size));
    defer conn_alloc.free(data);
    _ = try f.readAll(data);

    res.status = .ok;
    try res.headers.append("content-type", "text/html; charset=utf-8");
    try res.do();
    try writeAll(res, data);
}

fn parseMultipart(alloc: std.mem.Allocator, body: []const u8, content_type: []const u8) !std.StringHashMap([]u8) {
    var out = std.StringHashMap([]u8).init(alloc);

    const bpos = std.mem.indexOf(u8, content_type, "boundary=");
    if (bpos == null) return error.InvalidMultipart;
    const boundary = content_type[bpos.? + "boundary=".len ..];

    var fullb = std.ArrayList(u8).init(alloc);
    defer fullb.deinit();
    try fullb.appendSlice("--");
    try fullb.appendSlice(boundary);
    const delim = try fullb.toOwnedSlice();
    defer alloc.free(delim);

    var idx: usize = 0;
    while (true) {
        const start = std.mem.indexOfPos(u8, body, idx, delim) orelse break;
        var part_start = start + delim.len;
        if (part_start + 2 <= body.len and std.mem.eql(u8, body[part_start .. part_start + 2], "\r\n")) part_start += 2;
        if (part_start + 2 <= body.len and std.mem.eql(u8, body[part_start .. part_start + 2], "--")) break;

        const header_end = std.mem.indexOfPos(u8, body, part_start, "\r\n\r\n") orelse break;
        const headers_bytes = body[part_start .. header_end];
        const content_start = header_end + 4;
        const next = std.mem.indexOfPos(u8, body, content_start, delim) orelse body.len;

        var name: []const u8 = "";
        const dle = std.mem.indexOf(u8, headers_bytes, "\r\n") orelse headers_bytes.len;
        const disp = headers_bytes[0..dle];
        const nm = std.mem.indexOf(u8, disp, "name=\"") orelse disp.len;
        if (nm < disp.len) {
            const rest = disp[nm + "name=\"".len ..];
            const q = std.mem.indexOf(u8, rest, "\"") orelse rest.len;
            name = rest[0..q];
        }

        if (name.len > 0) {
            const part = body[content_start .. next - 2]; // strip \r\n
            var val = try alloc.alloc(u8, part.len);
            std.mem.copy(u8, val, part);
            try out.put(try alloc.dupe(u8, name), val);
        }

        idx = next;
    }
    return out;
}

fn urlencodedToMap(alloc: std.mem.Allocator, body: []const u8) !std.StringHashMap([]u8) {
    var out = std.StringHashMap([]u8).init(alloc);
    var it = std.mem.splitScalar(u8, body, '&');
    while (it.next()) |pair| {
        var kv = std.mem.splitScalar(u8, pair, '=');
        const k = kv.next() orelse continue;
        const v = kv.next() orelse "";
        const kd = try std.Uri.percentDecode(alloc, k);
        defer alloc.free(kd);
        const vd = try std.Uri.percentDecode(alloc, v);
        try out.put(kd, vd); // transfer kd, vd
    }
    return out;
}

fn handleStart(req: *Request, res: *Response, prov: Providers, conn_alloc: std.mem.Allocator) !void {
    // Read with arena; copy long-lived values to galloc only when needed
    var body = try req.reader().readAllAlloc(conn_alloc, 50 * 1024 * 1024);
    defer conn_alloc.free(body);

    const ct = req.headers.getFirstValue("content-type") orelse "";

    var seed_text: []u8 = "";
    var url_hint: []u8 = "";
    var target_chars: usize = 300_000;
    var max_sources: usize = 400;

    if (std.mem.startsWith(u8, ct, "multipart/form-data")) {
        var mp = try parseMultipart(conn_alloc, body, ct);
        defer {
            var it = mp.iterator();
            while (it.next()) |e| conn_alloc.free(e.value_ptr.*);
            mp.deinit();
        }
        if (mp.get("file")) |v| seed_text = try std.mem.dupe(conn_alloc, u8, v);
        if (mp.get("url")) |v| url_hint = try std.mem.dupe(conn_alloc, u8, v);
        if (mp.get("target_chars")) |v| target_chars = std.fmt.parseInt(usize, v, 10) catch target_chars;
        if (mp.get("max_sources")) |v| max_sources = std.fmt.parseInt(usize, v, 10) catch max_sources;
    } else if (std.mem.startsWith(u8, ct, "application/x-www-form-urlencoded")) {
        var fm = try urlencodedToMap(conn_alloc, body);
        defer {
            var it = fm.iterator();
            while (it.next()) |e| conn_alloc.free(e.value_ptr.*);
            fm.deinit();
        }
        if (fm.get("url")) |v| url_hint = try std.mem.dupe(conn_alloc, u8, v);
        if (fm.get("target_chars")) |v| target_chars = std.fmt.parseInt(usize, v, 10) catch target_chars;
        if (fm.get("max_sources")) |v| max_sources = std.fmt.parseInt(usize, v, 10) catch max_sources;
    } else {
        res.status = .bad_request;
        try res.do();
        return;
    }

    // If only URL is provided, fetch it into seed_text (arena-local)
    if (seed_text.len == 0 and url_hint.len > 0) {
        const fetched = httpGetText(url_hint, conn_alloc) catch "";
        defer if (fetched.len > 0) conn_alloc.free(fetched);
        if (fetched.len > 0) seed_text = try std.mem.dupe(conn_alloc, u8, fetched);
    }

    if (seed_text.len == 0 and url_hint.len == 0) {
        res.status = .bad_request;
        try res.headers.append("content-type", "application/json");
        try res.do();
        try writeAll(res, "{\"detail\":\"input required\"}");
        return;
    }

    // Normalize initial payload
    var norm: []u8 = seed_text;
    if (norm.len > 20_000) {
        const cp = try conn_alloc.alloc(u8, 20_000);
        std.mem.copy(u8, cp, norm[0..20_000]);
        norm = cp;
    }

    // Persist job id and job to global heap
    var idbuf: [32]u8 = undefined;
    std.crypto.random.bytes(&idbuf);
    const id = try std.fmt.allocPrint(galloc, "{s}", .{std.fmt.fmtSliceHexLower(&idbuf)});

    var job = try galloc.create(Job);
    job.* = .{
        .id = id,
        .state = .{ .status = "queued", .progress = 0, .started_at = nowTs(), .finished_at = 0, .queries_count = 0, .urls_count = 0 },
        .result = null,
    };

    jobs_rwlock.writerLock();
    defer jobs_rwlock.writerUnlock();
    try jobs.put(id, job);

    const prov_captured = prov;
    // Move work to background thread, dup needed inputs to global heap
    const norm_persist = if (norm.len > 0) blk: {
        const cp = try galloc.alloc(u8, norm.len);
        std.mem.copy(u8, cp, norm);
        break :blk cp;
    } else "" ;

    const url_hint_persist: ?[]u8 = if (url_hint.len > 0) blk2: {
        const cp = try galloc.alloc(u8, url_hint.len);
        std.mem.copy(u8, cp, url_hint);
        break :blk2 cp;
    } else null;

    _ = std.Thread.spawn(.{}, struct {
        fn f(ctx: struct {
            id: []const u8, seed: []const u8, url_hint: ?[]const u8, target: usize, maxs: usize, p: Providers
        }) void {
            researchRun(ctx.id, ctx.p, ctx.seed, ctx.url_hint, ctx.target, ctx.maxs);
        }
    }.f, .{ .id = id, .seed = norm_persist, .url_hint = url_hint_persist, .target = target_chars, .maxs = max_sources, .p = prov_captured }) catch {};

    res.status = .ok;
    try res.headers.append("content-type", "application/json; charset=utf-8");
    try res.do();
    try writeAll(res, "{\"job_id\":\"");
    try writeAll(res, id);
    try writeAll(res, "\"}");
}

fn handleStatus(req: *Request, res: *Response) !void {
    const base = "/research/status/";
    const path = req.head.target;
    if (path.len <= base.len) {
        res.status = .bad_request;
        try res.do();
        return;
    }
    const job_id = path[base.len..];

    jobs_rwlock.readerLock();
    const j = jobs.get(job_id);
    jobs_rwlock.readerUnlock();

    if (j == null) {
        res.status = .not_found;
        try res.do();
        return;
    }

    res.status = .ok;
    try res.headers.append("content-type", "application/json; charset=utf-8");
    try res.do();

    const s = j.?.*.state;
    var buf = std.ArrayList(u8).init(galloc);
    defer buf.deinit();
    try buf.appendSlice("{\"status\":\"");
    try buf.appendSlice(s.status);
    try buf.appendSlice("\",\"progress\":");
    try buf.writer().print("{}", .{s.progress});
    try buf.appendSlice(",\"started_at\":");
    try buf.writer().print("{}", .{s.started_at});
    try buf.appendSlice(",\"finished_at\":");
    try buf.writer().print("{}", .{s.finished_at});
    try buf.appendSlice(",\"queries\":");
    try buf.writer().print("{}", .{s.queries_count});
    try buf.appendSlice(",\"urls\":");
    try buf.writer().print("{}", .{s.urls_count});
    try buf.appendSlice("}");
    const out = try buf.toOwnedSlice();
    defer galloc.free(out);
    try writeAll(res, out);
}

fn handleSSE(req: *Request, res: *Response) !void {
    const base = "/research/stream/";
    const path = req.head.target;
    if (path.len <= base.len) {
        res.status = .bad_request;
        try res.do();
        return;
    }
    const job_id = path[base.len..];

    jobs_rwlock.readerLock();
    const j = jobs.get(job_id);
    jobs_rwlock.readerUnlock();

    if (j == null) {
        res.status = .not_found;
        try res.do();
        return;
    }

    res.status = .ok;
    try res.headers.append("content-type", "text/event-stream");
    try res.headers.append("cache-control", "no-cache");
    try res.headers.append("connection", "keep-alive");
    try res.do();

    while (true) {
        const s = j.?.*.state;

        var payload = std.ArrayList(u8).init(galloc);
        defer payload.deinit();
        try payload.appendSlice("data: ");
        var json = std.ArrayList(u8).init(galloc);
        defer json.deinit();
        try json.appendSlice("{\"status\":\"");
        try json.appendSlice(s.status);
        try json.appendSlice("\",\"progress\":");
        try json.writer().print("{}", .{s.progress});
        try json.appendSlice(",\"started_at\":");
        try json.writer().print("{}", .{s.started_at});
        try json.appendSlice(",\"finished_at\":");
        try json.writer().print("{}", .{s.finished_at});
        try json.appendSlice("}");
        const js = try json.toOwnedSlice();
        defer galloc.free(js);
        try payload.appendSlice(js);
        try payload.appendSlice("\n\n");
        const pl = try payload.toOwnedSlice();
        defer galloc.free(pl);
        try writeAll(res, pl);

        if (std.mem.eql(u8, s.status, "done")) break;
        std.time.sleep(1_000_000_000);
    }
}

fn handleDownload(req: *Request, res: *Response, conn_alloc: std.mem.Allocator) !void {
    const base = "/download/";
    const path = req.head.target;
    if (!std.mem.startsWith(u8, path, base) or !std.mem.endsWith(u8, path, ".zip")) {
        res.status = .bad_request;
        try res.do();
        return;
    }
    const job_id = path[base.len .. path.len - ".zip".len];

    jobs_rwlock.readerLock();
    const j = jobs.get(job_id);
    jobs_rwlock.readerUnlock();

    if (j == null or j.?.*.result == null) {
        res.status = .not_found;
        try res.do();
        return;
    }

    var mem = std.ArrayList(u8).init(conn_alloc);
    var stream = std.io.fixedBufferStream(try mem.addManyAsSlice(0, 0));
    var aw = stream.writer();
    var zip = std.zip.ArchiveWriter.init(conn_alloc, aw);
    defer zip.deinit();

    {
        var e = try zip.createFile("report.md", .{});
        try e.writeAll(j.?.*.result.?.report);
        try e.finish();
    }
    {
        var e2 = try zip.createFile("sources.json", .{});
        try e2.writeAll(j.?.*.result.?.sources_json);
        try e2.finish();
    }
    try zip.finish();

    const out = mem.toOwnedSlice() catch mem.items;

    res.status = .ok;
    try res.headers.append("content-type", "application/zip");
    try res.headers.append("content-disposition", "attachment; filename=\"report.zip\"");
    try res.do();
    try writeAll(res, out);
    conn_alloc.free(out);
}

// ========= Background pipeline =========

fn researchRun(id: []const u8, prov: Providers, seed_text_in: []const u8, url_hint_in: ?[]const u8, target_chars: usize, max_sources: usize) void {
    // Use a local arena to minimize heap churn during the whole pipeline
    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena.deinit();
    const A = arena.allocator();

    var norm = seed_text_in;
    if (norm.len == 0 and url_hint_in) |u| {
        const fetched = httpGetText(u, A) catch "";
        defer if (fetched.len > 0) A.free(fetched);
        if (fetched.len > 0) norm = fetched;
    }
    if (norm.len == 0) {
        jobs_rwlock.readerLock();
        const jp = jobs.get(id);
        jobs_rwlock.readerUnlock();
        if (jp) |p| {
            p.*.state.status = "error";
            p.*.state.finished_at = nowTs();
        }
        return;
    }
    if (norm.len > 20_000) {
        const cp = A.alloc(u8, 20_000) catch norm;
        if (cp.ptr != norm.ptr) {
            std.mem.copy(u8, cp, norm[0..20_000]);
            norm = cp;
        }
    }

    var st = JobState{
        .status = "starting",
        .progress = 0,
        .started_at = nowTs(),
        .finished_at = 0,
        .queries_count = 0,
        .urls_count = 0,
    };
    {
        jobs_rwlock.readerLock();
        const jp = jobs.get(id);
        jobs_rwlock.readerUnlock();
        if (jp) |p| p.*.state = st;
    }

    const deriv = deriveQueriesOutline(A, norm) catch {
        jobs_rwlock.readerLock();
        const jp = jobs.get(id);
        jobs_rwlock.readerUnlock();
        if (jp) |p| {
            p.*.state.status = "error";
            p.*.state.finished_at = nowTs();
        }
        return;
    };
    st.status = "searching";
    st.progress = 5;
    st.queries_count = deriv.queries.len;
    {
        jobs_rwlock.readerLock();
        const jp = jobs.get(id);
        jobs_rwlock.readerUnlock();
        if (jp) |p| p.*.state = st;
    }

    const urls = exaGather(prov, deriv.queries, 20, max_sources, A) catch std.ArrayList([]u8).init(A);
    st.status = "fetching";
    st.progress = 15;
    st.urls_count = urls.items.len;
    {
        jobs_rwlock.readerLock();
        const jp = jobs.get(id);
        jobs_rwlock.readerUnlock();
        if (jp) |p| p.*.state = st;
    }

    const docs = fetchDocs(urls.items, 120_000, A) catch std.ArrayList([]u8).init(A);
    st.progress = 30;
    {
        jobs_rwlock.readerLock();
        const jp = jobs.get(id);
        jobs_rwlock.readerUnlock();
        if (jp) |p| p.*.state = st;
    }

    var summaries = std.ArrayList([]u8).init(A);
    const cap = if (docs.items.len < 200) docs.items.len else 200;
    var i: usize = 0;
    while (i < cap) : (i += 1) {
        const s = summarizeDocAll(prov, docs.items[i], A);
        _ = summaries.append(s) catch {};
        const pgr = 30 + @min(40, @as(u8, @intCast((i * 40) / @max(1, cap))));
        st.progress = pgr;
        jobs_rwlock.readerLock();
        const jp = jobs.get(id);
        jobs_rwlock.readerUnlock();
        if (jp) |p| p.*.state = st;
    }

    st.status = "composing";
    {
        jobs_rwlock.readerLock();
        const jp = jobs.get(id);
        jobs_rwlock.readerUnlock();
        if (jp) |p| p.*.state = st;
    }

    const final_report = composeReport(prov, deriv.outline, summaries.items, target_chars, A);

    // Build sources.json
    var refs = std.ArrayList(u8).init(A);
    _ = refs.appendSlice("{\"queries\":[") catch {};
    for (deriv.queries, 0..) |q, qi| {
        if (qi > 0) _ = refs.appendSlice(",") catch {};
        const esc = jsonEscape(A, q) catch q;
        _ = refs.appendSlice("\"") catch {};
        _ = refs.appendSlice(esc) catch {};
        _ = refs.appendSlice("\"") catch {};
        if (esc.ptr != q.ptr) A.free(esc);
    }
    _ = refs.appendSlice("],\"urls\":[") catch {};
    for (urls.items, 0..) |u, ui| {
        if (ui > 0) _ = refs.appendSlice(",") catch {};
        const escu = jsonEscape(A, u) catch u;
        _ = refs.appendSlice("\"") catch {};
        _ = refs.appendSlice(escu) catch {};
        _ = refs.appendSlice("\"") catch {};
        if (escu.ptr != u.ptr) A.free(escu);
    }
    _ = refs.appendSlice("]}") catch {};
    const sources_json_tmp = refs.toOwnedSlice() catch refs.items;

    // Prefix + references
    var prefix = std.ArrayList(u8).init(A);
    _ = prefix.appendSlice("# Research Report\n\n") catch {};
    _ = prefix.appendSlice(final_report) catch {};
    _ = prefix.appendSlice("\n\n# References\n\n") catch {};
    for (urls.items) |u| {
        _ = prefix.appendSlice("- ") catch {};
        _ = prefix.appendSlice(u) catch {};
        _ = prefix.appendSlice("\n") catch {};
    }
    const report_md_tmp = prefix.toOwnedSlice() catch prefix.items;

    // Persist results to global heap
    const report_md = galloc.alloc(u8, report_md_tmp.len) catch report_md_tmp;
    if (report_md.ptr != report_md_tmp.ptr) {
        std.mem.copy(u8, report_md, report_md_tmp);
    }

    const sources_json = galloc.alloc(u8, sources_json_tmp.len) catch sources_json_tmp;
    if (sources_json.ptr != sources_json_tmp.ptr) {
        std.mem.copy(u8, sources_json, sources_json_tmp);
    }

    // Update job
    jobs_rwlock.readerLock();
    const jp = jobs.get(id);
    jobs_rwlock.readerUnlock();
    if (jp) |p| {
        p.*.result = .{ .report = report_md, .sources_json = sources_json };
        p.*.state.status = "done";
        p.*.state.progress = 100;
        p.*.state.finished_at = nowTs();
    }
}

// ========= Connection handler with branch hints + per-connection Arena =========

fn handleConn(conn: *http.Server.Connection, providers: Providers) void {
    defer conn.deinit();

    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena.deinit();
    const conn_alloc = arena.allocator();

    var req_r = conn.reader();
    var res_w = conn.writer();

    while (true) {
        var r = http.Server.Request{ .connection = conn.*, .reader = req_r };
        var s = http.Server.Response{ .writer = res_w };

        if (r.readHead() catch return) {
            const path = r.head.target;
            const method = r.head.method;

            if (@likely(method == .GET)) {
                if (@likely(std.mem.eql(u8, path, "/"))) {
                    _ = handleRoot(&s, conn_alloc) catch {};
                    continue;
                }
                if (@likely(std.mem.startsWith(u8, path, "/research/status/"))) {
                    _ = handleStatus(&r, &s) catch {};
                    continue;
                }
                if (@unlikely(std.mem.startsWith(u8, path, "/research/stream/"))) {
                    _ = handleSSE(&r, &s) catch {};
                    continue;
                }
                if (@unlikely(std.mem.startsWith(u8, path, "/download/")) and std.mem.endsWith(u8, path, ".zip")) {
                    _ = handleDownload(&r, &s, conn_alloc) catch {};
                    continue;
                }
            } else if (@unlikely(method == .POST)) {
                if (@unlikely(std.mem.eql(u8, path, "/research/start"))) {
                    _ = handleStart(&r, &s, providers, conn_alloc) catch {};
                    continue;
                }
            }

            s.status = .not_found;
            _ = s.do() catch {};
        } else break;
    }
}

// ========= Main =========

pub fn main() !void {
    defer std.debug.assert(gpa_state.deinit() == .ok);

    // Providers from env
    var env = std.process.env_map;

    const providers = Providers{
        .cerebras  = if (env.get("CEREBRAS_API_KEY")) |k| .{ .api_key = k } else null,
        .openai    = if (env.get("OPENAI_API_KEY"))   |k| .{ .api_key = k } else null,
        .anthropic = if (env.get("ANTHROPIC_API_KEY"))|k| .{ .api_key = k } else null,
        .gemini    = if (env.get("GOOGLE_API_KEY"))   |k| .{ .api_key = k } else null,
        .xai       = if (env.get("XAI_API_KEY"))      |k| .{ .api_key = k } else null,
        .exa       = if (env.get("EXA_API_KEY"))      |k| .{ .api_key = k } else null,
    };

    // Server init
    var server = http.Server.init(galloc, .{ .reuse_port = true });
    defer server.deinit();

    const port: u16 = blk: {
        const p = std.process.getEnvVarOwned(galloc, "PORT") catch null;
        if (p) |v| {
            defer galloc.free(v);
            break :blk std.fmt.parseInt(u16, v, 10) catch 8000;
        }
        break :blk 8000;
    };

    try server.listen(.{ .address = .{ .any = .{} }, .port = port });

    while (true) {
        var conn = try server.accept();
        std.Thread.spawn(.{}, handleConn, .{ &conn, providers }) catch {};
    }
}
```

Megjegyzés: a std.http szerver/kliens API-t használó, per-kapcsolat arena allokátorral és globális, belső poolt használó klienssel megvalósított minta a leginkább hordozható és reális út a valós teljesítménynyereséghez egyetlen fájlos programban, és illeszkedik a std dokumentált működéséhez és gyakorlati példáihoz [2][3].

Itt a teljes, Apple stílusú (HU) UI/UX frontend egyetlen, önálló index.html fájlban, amely közvetlenül együttműködik a korábban megírt Zig backend endpontjaival és az index.html kiszolgálásával a gyökérből [1][2].  
A felület tartalmaz hero szekciót, nagy tipográfiát, gradiens címsorokat, sticky navigációt, sima mikrointerakciókat, űrlapot URL/fájl indításhoz, élő SSE állapot streamet és kész riport letöltő gombot a /download/{id}.zip végponttal [1][2].  

### Fájl elhelyezés

- Mentsd az alábbi kódot index.html néven a szerver futtatási könyvtárába, mert a backend alapból onnan szolgálja ki a kezdőlapot a "/" GET kérésre [2].  
- Az űrlap a /research/start végpontot hívja multipart form-data-ként, ami kompatibilis a backenddel, és SSE-n figyeli a /research/stream/{job_id} eseményeket, amíg a státusz „done” nem lesz, majd felkínálja a /download/{job_id}.zip letöltést [2].  

### Design jegyek

- Minimalista tipográfia, nagy Headline méretezés, „gradient-text” stílus a hero címeknél, rendszerfont stack az Apple-élményhez hasonló vizuális hatással [1].  
- Sticky globális navigáció, tág ritmusok (spacing scale), sávos szekciók és kontrasztos fókuszjelölés hozzáférhetőséghez, a magyar nyelvi tartalom ritmusával [1].  
- Mikrolépéses animációk és görgetési átmenetek „prefers-reduced-motion” tiszteletben tartásával, nagy számok és kiemelt statok hero/feature blokkokban [1].  

