  <!-- App JS -->
  <script>
    function $(id){ return document.getElementById(id); }
    function scrollToSection(id){
      const el = document.getElementById(id);
      if(!el) return;
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    const form = $('form');
    const resetBtn = $('reset');
    const live = $('live');
    const bar = $('bar');
    const dot = $('dot');
    const statusText = $('statusText');
    const jobChip = $('jobChip');
    const jobIdSpan = $('jobId');
    const downloadBtn = $('download');
    const copyLinkBtn = $('copyLink');

    let currentJob = null;
    let es = null;
    let pollTimer = null;

    function setProgress(pct){
      const v = Math.max(0, Math.min(100, Number(pct)||0));
      bar.style.width = v + '%';
    }
    function setStatus(text, state){
      statusText.textContent = text;
      dot.classList.remove('ok','err');
      if(state === 'ok') dot.classList.add('ok');
      if(state === 'err') dot.classList.add('err');
    }
    function openDownload(jobId){
      downloadBtn.href = `/download/${encodeURIComponent(jobId)}.zip`;
      downloadBtn.hidden = false;
      copyLinkBtn.hidden = false;
    }
    function startPolling(jobId){
      if(pollTimer) { clearInterval(pollTimer); pollTimer = null; }
      pollTimer = setInterval(async ()=>{
        try{
          const r = await fetch(`/research/status/${encodeURIComponent(jobId)}`, { cache: 'no-store' });
          if(!r.ok) return;
          const j = await r.json();
          updateUIFromStatus(j, jobId);
        }catch(e){}
      }, 1500);
    }
    function stopPolling(){
      if(pollTimer) { clearInterval(pollTimer); pollTimer = null; }
    }
    function updateUIFromStatus(j, jobId){
      if(typeof j.progress === 'number') setProgress(j.progress);
      if(typeof j.status === 'string') setStatus(j.status, j.status === 'done' ? 'ok' : undefined);
      if(j.status === 'done'){
        openDownload(jobId);
        if(es){ es.close(); es = null; }
        stopPolling();
      }
    }

    function startSSE(jobId){
      try{
        if(es){ es.close(); es = null; }
        es = new EventSource(`/research/stream/${encodeURIComponent(jobId)}`);
        es.onmessage = (ev)=>{
          try{
            const j = JSON.parse(ev.data);
            updateUIFromStatus(j, jobId);
          }catch(e){}
        };
        es.onerror = ()=>{
          // Fallback poll
          if(es){ es.close(); es = null; }
          startPolling(jobId);
        };
      }catch(_){
        startPolling(jobId);
      }
    }

    form.addEventListener('submit', async (e)=>{
      e.preventDefault();
      // Build multipart form data
      const fd = new FormData();
      const url = $('url').value.trim();
      const file = $('file').files[0];
      const target = $('target_chars').value || '300000';
      const maxs = $('max_sources').value || '400';

      if(url) fd.append('url', url);
      if(file) fd.append('file', file);
      fd.append('target_chars', target);
      fd.append('max_sources', maxs);

      setProgress(0);
      setStatus('Indítás…', undefined);
      live.hidden = false;
      downloadBtn.hidden = true;
      copyLinkBtn.hidden = true;

      try{
        const r = await fetch('/research/start', { method:'POST', body: fd });
        if(!r.ok){
          setStatus(`Hiba: ${r.status}`, 'err');
          return;
        }
        const j = await r.json();
        const jobId = j.job_id || j.id || '';
        if(!jobId){
          setStatus('Hiba: hiányzó job_id', 'err');
          return;
        }
        currentJob = jobId;
        jobIdSpan.textContent = jobId;
        jobChip.hidden = false;
        setStatus('Folyamatban…', undefined);
        startSSE(jobId);
      }catch(err){
        setStatus('Hálózati hiba', 'err');
      }
    });

    resetBtn.addEventListener('click', ()=>{
      form.reset();
      live.hidden = true;
      setProgress(0);
      setStatus('Várakozás…', undefined);
      jobChip.hidden = true;
      jobIdSpan.textContent = '—';
      downloadBtn.hidden = true;
      copyLinkBtn.hidden = true;
      if(es){ es.close(); es = null; }
      stopPolling();
    });

    copyLinkBtn.addEventListener('click', async ()=>{
      if(!currentJob) return;
      const url = location.origin + `/download/${encodeURIComponent(currentJob)}.zip`;
      try{
        await navigator.clipboard.writeText(url);
        setStatus('Letöltési link kimásolva', 'ok');
      }catch(_){
        setStatus('Másolás sikertelen', 'err');
      }
    });
  </script>
</body>
</html>
